// Official notice links (ADR 0036, bipe-chat/bipe#245). Reference for the apps: a link in a notice from an
// account with a valid institution badge is clickable only on the institution's verified domains. The rule is
// lexical, not a URL parser, so Swift, Kotlin and Node agree on every input. Fail closed: anything else is plain text.

export const NOTICE_DOMAIN = /^[a-z0-9-]+(\.[a-z0-9-]+)+$/;
const AUTHORITY = /^[A-Za-z0-9.-]+$/;

/** True when `url` may be a clickable link in a notice from an institution with the verified `domains`. */
export function noticeLinkClickable(domains, url) {
  if (!Array.isArray(domains) || typeof url !== "string") return false;
  if (url.slice(0, 8).toLowerCase() !== "https://") return false;
  const rest = url.slice(8);
  const end = rest.search(/[/?#]/);
  const authority = end === -1 ? rest : rest.slice(0, end);
  // No user info (@), no port (:), no IP literal ([), no other characters.
  if (!AUTHORITY.test(authority)) return false;
  let host = authority.toLowerCase();
  if (host.endsWith(".")) host = host.slice(0, -1);
  if (!NOTICE_DOMAIN.test(host)) return false;
  return domains.some((d) => typeof d === "string" && NOTICE_DOMAIN.test(d) && (host === d || host.endsWith(`.${d}`)));
}
